#if DEBUG
import UIKit

// PUTIO_E2E_FIXTURE=large: a deterministic account sized like a heavy real one,
// for PutioUITests/PerformanceUITests. Routes it does not answer fall through
// to the default fixture, which it leaves untouched.
//
// Generated bytes are cached under Caches per app build, so a measured
// response is a file read rather than generation.
enum PutioE2ELargeFixture {
    struct Response {
        let statusCode: Int
        let contentType: String
        let body: Data
    }

    static let isEnabled = ProcessInfo.processInfo.environment["PUTIO_E2E_FIXTURE"] == "large"

    // An id encodes its type and folder, so a download route can answer any row
    // without regenerating the listing it came from:
    // type * 100_000_000 + folder * 10_000 + serial within that type.
    enum Kind: Int {
        case folder = 1, video, audio, image, pdf, other
    }

    // Root rows the perf tests open, first in the listing so they are on
    // screen without scrolling. Their names are what the tests wait for.
    enum Anchor {
        static let chainHead = folderID(1)
        static let sharedRoot = folderID(100)
        static let largeImage = fileID(.image, folder: 0, serial: 1)
        static let photo = fileID(.image, folder: 0, serial: 2)
        static let document = fileID(.pdf, folder: 0, serial: 1)

        static let largeImageName = "Perf fixture photo 8064x6048.jpg"
        static let documentName = "Perf fixture document 300 pages.pdf"
    }

    // Folders 1...12 form a chain, each the first child of the one before.
    static let chainDepth = 12
    private static let folderChildCount = 200
    private static let otherRootFolders = 38

    // Root mix: 40 folders, 1,000 videos, 300 audio, 400 images, 200 PDFs, 60 other.
    private static let rootMix: [(Kind, Int)] = [
        (.video, 1_000), (.audio, 300), (.image, 400), (.pdf, 200), (.other, 60)
    ]
    // Weights for the files in every other folder.
    private static let folderMix: [(Kind, Int)] = [
        (.video, 50), (.audio, 15), (.image, 20), (.pdf, 10), (.other, 5)
    ]

    static func response(method: String, url: URL) -> Response? {
        guard isEnabled, method == "GET" else { return nil }

        let path = url.path
        if path == "/v2/files/list" {
            let query = URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems ?? []
            let parentID = query.first(where: { $0.name == "parent_id" })?.value.flatMap(Int.init) ?? 0
            return listing(parentID: parentID)
        }

        if let id = downloadFileID(path: path) {
            return download(fileID: id)
        }

        return nil
    }

    /// Root ids the seeded downloads share with the listing.
    static func rootVideoIDs(count: Int) -> [Int] { (1...count).map { fileID(.video, folder: 0, serial: $0) } }
    static func rootAudioIDs(count: Int) -> [Int] { (1...count).map { fileID(.audio, folder: 0, serial: $0) } }

    // MARK: - Listings

    private static func listing(parentID: Int) -> Response {
        guard let folder = folderIndex(of: parentID) else {
            return Response(statusCode: 404, contentType: "application/json", body: Data("""
            {"status":"ERROR","status_code":404,"error_type":"NOT_FOUND","message":"No large fixture folder \(parentID)"}
            """.utf8))
        }

        let body = cached("list-\(parentID).json") {
            let children = children(ofFolder: folder)
            let payload: [String: Any] = [
                "status": "OK",
                "parent": parent(id: parentID, folder: folder),
                "files": children,
                "cursor": NSNull(),
                "total": children.count
            ]
            do {
                return try JSONSerialization.data(withJSONObject: payload, options: [.sortedKeys])
            } catch {
                preconditionFailure("Large fixture listing \(parentID) is not valid JSON: \(error)")
            }
        }
        return Response(statusCode: 200, contentType: "application/json", body: body)
    }

    private static func parent(id: Int, folder: Int) -> [String: Any] {
        if folder == 0 {
            return [
                "id": 0, "name": "Your Files", "parent_id": 0, "size": 0,
                "created_at": timestamp(secondsAgo: 94_608_000), "updated_at": timestamp(secondsAgo: 60),
                "file_type": "FOLDER", "folder_type": "REGULAR", "is_shared": false, "sort_by": "NAME_ASC",
                "icon": "https://api.put.io/images/file-types/folder.svg"
            ]
        }

        var random = SeededRandom(state: UInt64(id))
        return file(id: id, kind: .folder, parentID: parentFolderID(of: folder), random: &random, name: folderName(folder))
    }

    private static func children(ofFolder folder: Int) -> [[String: Any]] {
        var random = SeededRandom(state: 0x5EED_0000 + UInt64(folder))
        let parentID = folder == 0 ? 0 : folderID(folder)

        if folder == 0 {
            var rows: [[String: Any]] = [
                file(id: Anchor.chainHead, kind: .folder, parentID: 0, random: &random, name: folderName(1)),
                file(id: Anchor.sharedRoot, kind: .folder, parentID: 0, random: &random, name: folderName(100)),
                file(id: Anchor.largeImage, kind: .image, parentID: 0, random: &random, name: Anchor.largeImageName),
                file(id: Anchor.photo, kind: .image, parentID: 0, random: &random, name: "Perf fixture photo 4032x3024.jpg"),
                file(id: Anchor.document, kind: .pdf, parentID: 0, random: &random, name: Anchor.documentName)
            ]

            var kinds = (1...otherRootFolders).map { _ in Kind.folder }
            for (kind, count) in rootMix {
                let anchored = rows.filter { ($0["file_type"] as? String) == kind.traits.fileType }.count
                kinds += Array(repeating: kind, count: count - anchored)
            }
            kinds.shuffle(using: &random)

            var serials: [Kind: Int] = [.image: 2, .pdf: 1]
            for kind in kinds {
                let serial = (serials[kind] ?? 0) + 1
                serials[kind] = serial
                let id = kind == .folder ? folderID(200 + serial) : fileID(kind, folder: 0, serial: serial)
                rows.append(file(id: id, kind: kind, parentID: 0, random: &random))
            }

            // The backend's page cap, so one page holds everything.
            assert(rows.count == 2_000)
            return rows
        }

        var rows: [[String: Any]] = []
        if (1..<chainDepth).contains(folder) {
            rows.append(file(id: folderID(folder + 1), kind: .folder, parentID: parentID, random: &random, name: folderName(folder + 1)))
        }

        var serials: [Kind: Int] = [:]
        while rows.count < folderChildCount {
            let kind = random.weighted(folderMix)
            let serial = (serials[kind] ?? 0) + 1
            serials[kind] = serial
            rows.append(file(id: fileID(kind, folder: folder, serial: serial), kind: kind, parentID: parentID, random: &random))
        }
        return rows
    }

    private static func file(
        id: Int,
        kind: Kind,
        parentID: Int,
        random: inout SeededRandom,
        name: String? = nil
    ) -> [String: Any] {
        let traits = kind.traits
        let fileExtension = traits.extensions[random.int(below: traits.extensions.count)]
        let name = name ?? (generatedName(random: &random) + (fileExtension.isEmpty ? "" : ".\(fileExtension)"))
        // Seconds to three years back, spread evenly on a log scale.
        let updatedAgo = Int(pow(10, random.double(in: 1.8...7.98)))
        let createdAgo = updatedAgo + random.int(below: 2_592_000)

        var row: [String: Any] = [
            "id": id,
            "name": name,
            "parent_id": parentID,
            // Bytes to terabytes.
            "size": Int64(pow(10, random.double(in: 1...12.5))),
            "created_at": timestamp(secondsAgo: createdAgo),
            "updated_at": timestamp(secondsAgo: updatedAgo),
            "file_type": traits.fileType,
            "is_shared": false,
            "is_hidden": false,
            "icon": "https://api.put.io/images/file-types/\(traits.icon).svg",
            "content_type": traits.contentType,
            "extension": fileExtension.isEmpty ? NSNull() : fileExtension,
            "crc32": String(format: "%08x", UInt32(truncatingIfNeeded: random.next())),
            "first_accessed_at": random.int(below: 3) == 0 ? NSNull() : timestamp(secondsAgo: updatedAgo / 2)
        ]

        switch kind {
        case .folder:
            row["folder_type"] = id == Anchor.sharedRoot ? "SHARED_ROOT" : "REGULAR"
            row["sort_by"] = "NAME_ASC"
        case .video:
            let width = [1280, 1920, 3840][random.int(below: 3)]
            let isMP4 = random.int(below: 2) == 0
            row["folder_type"] = "REGULAR"
            row["screenshot"] = "https://api.put.io/v2/files/\(id)/screenshot"
            row["start_from"] = random.int(below: 10) == 0 ? 60 + random.int(below: 3_000) : 0
            row["need_convert"] = !isMP4 && random.int(below: 4) == 0
            row["is_mp4_available"] = isMP4
            row["mp4_size"] = isMP4 ? Int64(pow(10, random.double(in: 8...10))) : 0
            row["opensubtitles_hash"] = String(format: "%016llx", random.next())
            row["video_metadata"] = [
                "width": width,
                "height": width * 9 / 16,
                "codec": "h264",
                "duration": Double(60 + random.int(below: 10_000)),
                "aspect_ratio": 1.777
            ]
        case .image:
            row["folder_type"] = "REGULAR"
            row["screenshot"] = "https://api.put.io/v2/files/\(id)/screenshot"
        case .audio, .pdf, .other:
            row["folder_type"] = "REGULAR"
        }

        return row
    }

    private static let words = [
        "archive", "summer", "lecture", "session", "remaster", "concert", "episode", "draft",
        "holiday", "backup", "interview", "trailer", "album", "scan", "invoice", "notes",
        "final", "extended", "director's cut", "live", "demo", "proxy", "raw", "export",
        "東京", "夜景", "音楽", "写真", "記録", "서울", "📷", "🎬", "🎵", "✨"
    ]

    // 10 to 120 characters. Generated, so no title belongs to a real user.
    private static func generatedName(random: inout SeededRandom) -> String {
        let target = 10 + random.int(below: 111)
        var name = ""
        while name.count < target {
            if !name.isEmpty { name += random.int(below: 6) == 0 ? " - " : " " }
            name += random.int(below: 5) == 0
                ? String(1990 + random.int(below: 36))
                : words[random.int(below: words.count)]
        }
        return String(name.prefix(target))
    }

    private static func folderName(_ folder: Int) -> String {
        switch folder {
        case 1...chainDepth: return "Perf fixture level \(folder)"
        case 100: return "Items shared with you"
        default: return "Perf fixture folder \(folder - 200)"
        }
    }

    // MARK: - Ids

    private static func folderID(_ folder: Int) -> Int {
        Kind.folder.rawValue * 100_000_000 + folder
    }

    private static func fileID(_ kind: Kind, folder: Int, serial: Int) -> Int {
        kind.rawValue * 100_000_000 + folder * 10_000 + serial
    }

    static func kind(of id: Int) -> Kind? {
        Kind(rawValue: id / 100_000_000)
    }

    /// The folder index a folder id lists, or nil when the fixture has no such folder.
    private static func folderIndex(of id: Int) -> Int? {
        if id == 0 { return 0 }
        guard kind(of: id) == .folder else { return nil }

        let folder = id % 100_000_000
        let known = (1...chainDepth).contains(folder)
            || folder == 100
            || (201...(200 + otherRootFolders)).contains(folder)
        return known ? folder : nil
    }

    private static func parentFolderID(of folder: Int) -> Int {
        (2...chainDepth).contains(folder) ? folderID(folder - 1) : 0
    }

    private static func downloadFileID(path: String) -> Int? {
        let components = path.split(separator: "/")
        guard components.count == 4,
              components[0] == "v2", components[1] == "files", components[3] == "download" else {
            return nil
        }
        return Int(components[2])
    }

    // MARK: - Cache

    private static let cacheLock = NSLock()

    static func cached(_ name: String, make: () -> Data) -> Data {
        cacheLock.lock()
        defer { cacheLock.unlock() }

        let url = cacheDirectory.appendingPathComponent(name)
        if let data = try? Data(contentsOf: url, options: .mappedIfSafe) {
            return data
        }

        let data = make()
        try? data.write(to: url, options: .atomic)
        return data
    }

    // Keyed by the executable's modification date, so a rebuild that changes
    // the generator never serves bytes the previous build wrote.
    private static let cacheDirectory: URL = {
        let caches = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0]
        let root = caches.appendingPathComponent("putio-e2e-large", isDirectory: true)
        let modified = (try? Bundle.main.executableURL?.resourceValues(forKeys: [.contentModificationDateKey]))?
            .contentModificationDate?.timeIntervalSince1970 ?? 0
        let directory = root.appendingPathComponent(String(Int(modified)), isDirectory: true)

        if !FileManager.default.fileExists(atPath: directory.path) {
            try? FileManager.default.removeItem(at: root)
            try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        }
        return directory
    }()

    // MARK: - Formatting

    // Fixed rather than relative to now, so every launch serves the same bytes
    // and the cache stays valid.
    private static let referenceDate = Date(timeIntervalSince1970: 1_767_225_600) // 2026-01-01T00:00:00Z

    // The API's naive UTC form, without a zone, which costs the SDK's parser
    // the same retries it pays in production.
    private static let timestampFormatter: ISO8601DateFormatter = {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withFullDate, .withTime, .withDashSeparatorInDate, .withColonSeparatorInTime]
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        return formatter
    }()

    private static func timestamp(secondsAgo: Int) -> String {
        timestampFormatter.string(from: referenceDate.addingTimeInterval(-TimeInterval(secondsAgo)))
    }
}

private struct Traits {
    let fileType: String
    let icon: String
    let contentType: String
    let extensions: [String]
}

private extension PutioE2ELargeFixture.Kind {
    var traits: Traits {
        switch self {
        case .folder: return Traits(fileType: "FOLDER", icon: "folder", contentType: "application/x-directory", extensions: [""])
        case .video: return Traits(fileType: "VIDEO", icon: "video", contentType: "video/x-matroska", extensions: ["mkv", "mp4", "avi"])
        case .audio: return Traits(fileType: "AUDIO", icon: "audio", contentType: "audio/mpeg", extensions: ["mp3", "flac", "m4a"])
        case .image: return Traits(fileType: "IMAGE", icon: "image", contentType: "image/jpeg", extensions: ["jpg", "png", "heic"])
        case .pdf: return Traits(fileType: "PDF", icon: "pdf", contentType: "application/pdf", extensions: ["pdf"])
        case .other: return Traits(fileType: "OTHER", icon: "file", contentType: "application/octet-stream", extensions: ["zip", "srt", "nfo", "txt"])
        }
    }
}

/// SplitMix64: the same sequence on every run, unlike the system generator.
struct SeededRandom: RandomNumberGenerator {
    var state: UInt64

    mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return z ^ (z >> 31)
    }

    mutating func int(below bound: Int) -> Int {
        Int.random(in: 0..<bound, using: &self)
    }

    mutating func double(in range: ClosedRange<Double>) -> Double {
        Double.random(in: range, using: &self)
    }

    mutating func weighted<T>(_ choices: [(T, Int)]) -> T {
        var pick = int(below: choices.reduce(0) { $0 + $1.1 })
        for (choice, weight) in choices {
            if pick < weight { return choice }
            pick -= weight
        }
        return choices[choices.count - 1].0
    }
}
#endif
